code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    plus = {}
    minus = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                continue
            plus.setdefault(c - r, set()).add(r)
            minus.setdefault(c + r, set()).add(r)
    for b, plus_rows in plus.items():
        for d, minus_rows in minus.items():
            if (b + d) % 2:
                continue
            apex_r = (d - b) // 2
            apex_c = (b + d) // 2
            if not (0 <= apex_r < h and 0 <= apex_c < w and grid[apex_r][apex_c] != 0):
                continue
            for r in plus_rows & minus_rows:
                c1, c2 = b + r, d - r
                if c1 == c2 or not (0 <= c1 < w and 0 <= c2 < w):
                    continue
                if grid[r][c1] == 0 or grid[r][c2] == 0:
                    continue
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if out[r][c] == 0:
                        out[r][c] = 2
    return out
'''
